-- Recipes part 2/4: insert-only.
do $seed$
declare d jsonb := '[{"slug":"bhuna-gosht","name":"Beef Bhuna Gosht","description":"Beef slow-cooked and then stir-fried until the masala darkens and clings to the meat.","category":"Main Course","cuisine":"Pakistani","minutes":90,"servings":4,"taste":{"sweet":0,"salty":6,"sour":3,"spicy":7},"lines":[["Beef Boneless",750,"750 g"],["Onion",250,"2, sliced"],["Tomato",200,"2"],["Ginger Garlic Paste",25,"1 1/2 tbsp"],["Yogurt (Dahi)",100,"1/2 cup"],["Red Chilli Powder",8,"2 tsp"],["Coriander Powder",6,"1 1/2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Garam Masala",4,"1 tsp"],["Cooking Oil",80,"1/3 cup"],["Salt",10,"1 3/4 tsp"],["Green Chilli",15,"3"]],"steps":["Fry the onions until golden; add the beef and ginger garlic paste and sear well.","Add the spices, tomatoes and yogurt; cook for 5 minutes.","Add 2 cups water, cover and cook on low heat for 1 hour until tender.","Uncover and bhuno on high heat, stirring, until the masala is dark and dry. Add green chillies and garam masala."]},{"slug":"mutton-pulao","name":"Mutton Pulao","description":"Fragrant rice cooked in a whole-spice mutton stock (yakhni) with fried onions.","category":"Rice","cuisine":"Pakistani","minutes":120,"servings":6,"taste":{"sweet":1,"salty":6,"sour":1,"spicy":3},"lines":[["Mutton",750,"750 g"],["Basmati Rice",500,"2 1/2 cups, soaked"],["Onion",200,"2, sliced"],["Ginger",20,"1 piece"],["Garlic",20,"1 bulb"],["Coriander Seeds (Sabut Dhania)",8,"1 tbsp"],["Fennel Seeds (Saunf)",5,"1 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Black Cardamom (Bari Elaichi)",2,"2"],["Cloves (Laung)",1,"5"],["Cooking Oil",100,"1/2 cup"],["Salt",15,"2 1/2 tsp"],["Yogurt (Dahi)",100,"1/2 cup"]],"steps":["Tie the ginger, garlic, coriander and fennel seeds in a muslin bag; boil with the mutton in 6 cups water for 1 hour to make yakhni.","Fry the onions golden in oil, add cumin, cardamom and cloves, then the mutton pieces and yogurt.","Add 4 cups of strained yakhni and salt; bring to a boil.","Add the drained rice, cook until the water is absorbed, then steam on low heat for 15 minutes."]},{"slug":"rohu-fish-curry","name":"Rohu Fish Curry","description":"River fish simmered in a tangy tomato and mustard-seed gravy.","category":"Main Course","cuisine":"Pakistani","minutes":40,"servings":4,"taste":{"sweet":0,"salty":6,"sour":5,"spicy":6},"lines":[["Rohu Fish",750,"750 g, steaks"],["Tomato",300,"3"],["Onion",150,"1 large"],["Ginger Garlic Paste",15,"1 tbsp"],["Mustard Seeds (Sarson)",3,"1 tsp"],["Turmeric (Haldi)",3,"1 tsp"],["Red Chilli Powder",6,"1 1/2 tsp"],["Coriander Powder",5,"1 tsp"],["Tamarind (Imli)",15,"1 tbsp pulp"],["Mustard Oil",50,"1/4 cup"],["Salt",8,"1 1/2 tsp"],["Fresh Coriander",10,"chopped"]],"steps":["Rub the fish with turmeric and salt and lightly fry; set aside.","In the same oil splutter the mustard seeds, then fry the onion and ginger garlic paste.","Add tomatoes and spices; cook until soft, then add 1 1/2 cups water and the tamarind.","Slide in the fish and simmer for 8 minutes without stirring. Garnish with coriander."]},{"slug":"fish-tikka","name":"Surmai Fish Tikka","description":"King fish cubes marinated in yogurt, lemon and carom seeds, then grilled.","category":"Snacks","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":0,"salty":6,"sour":5,"spicy":6},"lines":[["Surmai Fish (King Fish)",600,"600 g, cubed"],["Yogurt (Dahi)",80,"1/3 cup"],["Lemon",30,"juice of 1"],["Carom Seeds (Ajwain)",2,"1/2 tsp"],["Ginger Garlic Paste",15,"1 tbsp"],["Kashmiri Chilli Powder",5,"1 1/2 tsp"],["Gram Flour (Besan)",15,"1 1/2 tbsp"],["Chaat Masala",3,"1 tsp"],["Salt",6,"1 tsp"],["Cooking Oil",20,"for basting"]],"steps":["Marinate the fish with lemon and salt for 10 minutes.","Mix in yogurt, besan, carom seeds, ginger garlic paste and chilli; rest for 20 minutes.","Grill on skewers for 8-10 minutes, basting with oil.","Sprinkle chaat masala and serve with lemon wedges."]},{"slug":"anda-curry","name":"Anda Curry","description":"Boiled eggs in a home-style onion-tomato masala.","category":"Main Course","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":6,"sour":4,"spicy":6},"lines":[["Eggs",300,"6, boiled and peeled"],["Onion",200,"2"],["Tomato",250,"2 large"],["Ginger Garlic Paste",15,"1 tbsp"],["Red Chilli Powder",5,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Coriander Powder",5,"1 tsp"],["Garam Masala",2,"1/2 tsp"],["Cooking Oil",50,"1/4 cup"],["Salt",7,"1 1/4 tsp"],["Fresh Coriander",10,"chopped"],["Green Chilli",10,"2"]],"steps":["Lightly fry the boiled eggs with a pinch of turmeric; set aside.","Fry the onions golden, add ginger garlic paste, tomatoes and spices; bhuno until the oil separates.","Add 1 cup water, then the eggs; simmer for 8 minutes.","Finish with garam masala, green chillies and coriander."]},{"slug":"palak-paneer","name":"Palak Paneer","description":"Cubes of paneer in a smooth, garlicky spinach gravy.","category":"Vegetables","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":1,"salty":5,"sour":2,"spicy":4},"lines":[["Spinach",500,"500 g"],["Paneer",250,"250 g, cubed"],["Onion",120,"1"],["Tomato",100,"1"],["Garlic",15,"5 cloves"],["Ginger",10,"1 inch"],["Green Chilli",10,"2"],["Cumin (Zeera)",3,"1 tsp"],["Garam Masala",2,"1/2 tsp"],["Fresh Cream (Malai)",40,"3 tbsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"]],"steps":["Blanch the spinach with the green chillies for 2 minutes, cool and blend smooth.","Heat oil, crackle the cumin, then fry onion, garlic and ginger until golden.","Add the tomato and cook until soft; add the spinach puree and salt and simmer for 5 minutes.","Add the paneer and garam masala, simmer 3 minutes and finish with cream."]},{"slug":"matar-paneer","name":"Matar Paneer","description":"Peas and paneer in a lightly spiced tomato gravy.","category":"Vegetables","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":2,"salty":5,"sour":3,"spicy":5},"lines":[["Paneer",250,"250 g"],["Green Peas",250,"1 1/2 cups"],["Tomato",300,"3"],["Onion",120,"1"],["Ginger Garlic Paste",15,"1 tbsp"],["Red Chilli Powder",4,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Coriander Powder",5,"1 tsp"],["Garam Masala",2,"1/2 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"]],"steps":["Fry the onion until soft, add ginger garlic paste and spices.","Add pureed tomatoes and cook until the oil separates.","Add peas and 1 cup water; cook for 8 minutes.","Add paneer cubes and garam masala and simmer for 4 minutes."]},{"slug":"mix-sabzi","name":"Mix Sabzi","description":"Seasonal vegetables cooked together with cumin and a little tomato.","category":"Vegetables","cuisine":"Pakistani","minutes":35,"servings":4,"taste":{"sweet":2,"salty":5,"sour":2,"spicy":4},"lines":[["Potato",200,"2"],["Carrot",150,"2"],["Green Peas",150,"1 cup"],["Cauliflower",200,"1 small"],["Green Beans (Fali)",100,"a handful"],["Tomato",150,"1 large"],["Onion",100,"1"],["Cumin (Zeera)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",7,"1 1/4 tsp"]],"steps":["Crackle cumin in oil and fry the onion until soft.","Add tomato and spices and cook for 3 minutes.","Add all vegetables and salt, cover and cook on low heat for 15-20 minutes until tender.","Uncover and stir-fry for 2 minutes."]},{"slug":"aloo-matar","name":"Aloo Matar","description":"Potatoes and peas in a simple home-style tomato curry.","category":"Vegetables","cuisine":"Pakistani","minutes":30,"servings":4,"taste":{"sweet":2,"salty":5,"sour":3,"spicy":5},"lines":[["Potato",400,"3 medium, cubed"],["Green Peas",250,"1 1/2 cups"],["Tomato",250,"2"],["Onion",100,"1"],["Ginger Garlic Paste",10,"2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",5,"1 tsp"],["Cumin (Zeera)",3,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",7,"1 1/4 tsp"],["Fresh Coriander",10,"chopped"]],"steps":["Crackle cumin in oil, add onion and ginger garlic paste and fry until golden.","Add tomatoes and spices; cook until soft.","Add potatoes, peas and 1 1/2 cups water; cover and cook for 15 minutes.","Garnish with coriander."]},{"slug":"aloo-methi","name":"Aloo Methi","description":"Potatoes stir-fried with fresh fenugreek leaves and garlic.","category":"Vegetables","cuisine":"Pakistani","minutes":30,"servings":4,"taste":{"sweet":1,"salty":5,"sour":1,"spicy":4},"lines":[["Potato",500,"4 medium"],["Fenugreek Leaves (Methi)",150,"2 bunches, chopped"],["Garlic",15,"5 cloves"],["Cumin (Zeera)",3,"1 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Flakes (Kuti Lal Mirch)",3,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"]],"steps":["Crackle cumin and garlic in oil.","Add potatoes, turmeric, chilli and salt; cover and cook for 10 minutes.","Add the methi and stir-fry on medium heat until the potatoes are tender and the leaves wilt (8 minutes)."]},{"slug":"karela-qeema","name":"Karela Qeema","description":"Bitter gourd cooked with spiced beef mince; the bitterness balances the rich qeema.","category":"Main Course","cuisine":"Pakistani","minutes":55,"servings":4,"taste":{"sweet":1,"salty":6,"sour":3,"spicy":6},"lines":[["Bitter Gourd (Karela)",400,"4, scraped and sliced"],["Beef Qeema",400,"400 g"],["Onion",200,"2"],["Tomato",200,"2"],["Ginger Garlic Paste",15,"1 tbsp"],["Red Chilli Powder",6,"1 1/2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Coriander Powder",5,"1 tsp"],["Cooking Oil",70,"1/3 cup"],["Salt",10,"1 3/4 tsp"]],"steps":["Rub the karela with salt for 30 minutes, rinse and fry until browned; set aside.","Fry onions, add ginger garlic paste and the qeema and cook until browned.","Add tomatoes and spices and bhuno until the oil separates.","Add the karela, cover and cook on low heat for 10 minutes."]},{"slug":"tinda-masala","name":"Tinda Masala","description":"Tender apple gourds in a light tomato and onion masala.","category":"Vegetables","cuisine":"Pakistani","minutes":30,"servings":4,"taste":{"sweet":1,"salty":5,"sour":3,"spicy":4},"lines":[["Apple Gourd (Tinda)",500,"6, peeled and quartered"],["Tomato",200,"2"],["Onion",100,"1"],["Ginger Garlic Paste",10,"2 tsp"],["Turmeric (Haldi)",2,"1/2 tsp"],["Red Chilli Powder",4,"1 tsp"],["Coriander Powder",5,"1 tsp"],["Cooking Oil",40,"3 tbsp"],["Salt",6,"1 tsp"],["Fresh Coriander",8,"chopped"]],"steps":["Fry the onion and ginger garlic paste until golden.","Add tomatoes and spices and cook until soft.","Add the tinda and 1/2 cup water; cover and cook for 15 minutes until tender.","Garnish with coriander."]}]'::jsonb; r jsonb; rid bigint; i int; missing text;
begin
select string_agg(distinct l->>0, ', ') into missing from jsonb_array_elements(d) r2, jsonb_array_elements(r2->'lines') l where not exists (select 1 from public.ingredients x where x.name = l->>0);
if missing is not null then raise exception 'Unknown ingredients: %', missing; end if;
for r in select * from jsonb_array_elements(d) loop
insert into public.curated_recipes(slug, name, description, category, cuisine, minutes, servings, taste, status, source) values (r->>'slug', r->>'name', r->>'description', r->>'category', r->>'cuisine', (r->>'minutes')::int, (r->>'servings')::int, r->'taste', 'published', 'curated') on conflict (slug) do nothing returning id into rid;
continue when rid is null;
for i in 0 .. jsonb_array_length(r->'lines') - 1 loop
insert into public.recipe_ingredients(recipe_id, ingredient_id, position, grams, display) select rid, x.id, i + 1, (r->'lines'->i->>1)::numeric, r->'lines'->i->>2 from public.ingredients x where x.name = r->'lines'->i->>0;
end loop;
for i in 0 .. jsonb_array_length(r->'steps') - 1 loop
insert into public.recipe_steps(recipe_id, position, body) values (rid, i + 1, r->'steps'->>i);
end loop;
end loop;
end $seed$;
select count(*) as published_recipes from public.curated_recipes where status = 'published';